{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {}
    children_map = {}
    for node in nodes:
        nid = node['id']
        node_map[nid] = node
        children_map.setdefault(nid, [])
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children_map.setdefault(parent, []).append(node['id'])
    retained = set(node_map.keys())
    removal_order = []
    if 'root' not in node_map:
        raise ValueError('No root node')
    for sym in required_symbols:
        if not any(node['symbol'] == sym for node in node_map.values()):
            raise ValueError(f'Required symbol {sym} not present')
    def get_eligible():
        eligible = []
        for nid in retained:
            node = node_map[nid]
            if not node['removable']:
                continue
            if node['symbol'] in required_symbols:
                continue
            if nid == 'root':
                continue
            children = children_map.get(nid, [])
            if any(c in retained for c in children):
                continue
            temp_retained = retained - {nid}
            if all(any(node_map[rid]['symbol'] == sym for rid in temp_retained) for sym in required_symbols):
                eligible.append(nid)
        return eligible
    while True:
        eligible = get_eligible()
        if not eligible:
            break
        best = sorted(eligible, key=lambda nid: (-node_map[nid]['depth'], nid))[0]
        removal_order.append(best)
        retained.remove(best)
    return {'retained_ids': sorted(retained), 'removal_order': removal_order}"
}
